"use client";

import { useState, useMemo } from "react";
import { useHasMounted } from "@/hooks/use-has-mounted";
import { useSearchParams } from "next/navigation";
import { toast } from "react-hot-toast";

import { addAlternativeAsset, updateAlternativeAsset, deleteAlternativeAsset } from "./actions";
import { useFinanceData, type FinanceData } from "@/hooks/use-finance-data";
import { format } from "date-fns";
import { useSubmitLock } from "@/hooks/use-submit-lock";
import { Drawer } from "@/components/ui/drawer";
import { Trash2 } from "lucide-react";
import PnLValue from "@/components/pnl-value";

import { ResponsiveContainer, BarChart, Bar, PieChart, Pie, Cell, CartesianGrid, XAxis, YAxis, Tooltip as RechartsTooltip, Legend } from "@/components/ui/recharts";

import AlternativeAssetsDataTable from "./components/AlternativeAssetsDataTable";
import { getChartColour } from "@/lib/chart-colours";

const CATEGORIES = [
  { label: "Real Estate", icon: "🏙️" },
  { label: "Gold / Precious Metals", icon: "🏆" },
  { label: "Physical Assets", icon: "📦" },
  { label: "Collectibles", icon: "🎨" },
  { label: "Private Equity", icon: "🤝" },
  { label: "Crypto (Cold Storage)", icon: "🔐" },
  { label: "Others", icon: "🎯" },
];

export default function AlternativeAssetsClient({ initialData, isSubComponent = false }: { initialData?: FinanceData; isSubComponent?: boolean }) {
  const { data: { alternativeAssets, ledgerLogs, accounts }, mutate } = useFinanceData(initialData);
  const searchParams = useSearchParams();
  const [showAddModal, setShowAddModal] = useState(searchParams?.get("action") === "new");
  const [submitting, withLock] = useSubmitLock();
  const [editingId, setEditingId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<"dashboard" | "inventory" | "history">(isSubComponent ? "inventory" : "dashboard");

  const mounted = useHasMounted();

  const assetLogs = useMemo(() => {
    return ledgerLogs
      .filter(log => log.source_type === "alternative_asset" || log.details?.toLowerCase().includes("asset") || log.details?.toLowerCase().includes("physical asset"))
      .sort((a, b) => new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime());
  }, [ledgerLogs]);

  const [formData, setFormData] = useState({
    name: "", category: "", purchase_price: "", current_value: "",
    purchase_date: "", notes: "", account_id: "",
  });

  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<any>(null);

  const searchResults = useMemo(() => {
    if (searchQuery.length < 1) return CATEGORIES;
    return CATEGORIES.filter(c => 
      c.label.toLowerCase().includes(searchQuery.toLowerCase()) || 
      c.icon.includes(searchQuery)
    );
  }, [searchQuery]);

  const handleCategorySelect = (cat: any) => {
    setSelectedCategory(cat);
    setSearchQuery("");
    setFormData({ ...formData, category: cat.label });
  };

  const stats = useMemo(() => {
    const totalValue = alternativeAssets.reduce((s, a) => s + Number(a.current_value), 0);
    const totalCost = alternativeAssets.reduce((s, a) => s + Number(a.purchase_price), 0);
    const netGrowth = totalValue - totalCost;
    const growthPercent = totalCost > 0 ? (netGrowth / totalCost) * 100 : 0;
    return { totalValue, totalCost, netGrowth, growthPercent };
  }, [alternativeAssets]);

  const pieChartData = useMemo(() => {
    const map: Record<string, number> = {};
    alternativeAssets.forEach(a => {
      map[a.category] = (map[a.category] || 0) + Number(a.current_value);
    });
    return Object.entries(map).map(([name, value], idx) => {
      const fill = getChartColour(idx);
      return { name, value, fill };
    });
  }, [alternativeAssets]);

  const barChartData = useMemo(() => {
    return [...alternativeAssets].sort((a, b) => Number(b.current_value) - Number(a.current_value)).slice(0, 10).map(a => ({
      name: a.name.length > 15 ? a.name.substring(0, 15) + '...' : a.name,
      Cost: Number(a.purchase_price),
      Value: Number(a.current_value)
    }));
  }, [alternativeAssets]);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    await withLock(async () => {
      const { account_id, ...assetData } = formData;
      const payload = {
        ...assetData,
        purchase_price: parseFloat(formData.purchase_price),
        current_value: parseFloat(formData.current_value),
        purchase_date: formData.purchase_date || undefined,
      };

      const res = editingId 
         ? await updateAlternativeAsset(editingId, payload)
         : await addAlternativeAsset({ ...payload, account_id });

      if (!res.error) {
        toast.success(editingId ? "Asset updated" : "Asset established");
        setShowAddModal(false);
        setEditingId(null);
        setSelectedCategory(null);
        setFormData({ name: "", category: "", purchase_price: "", current_value: "", purchase_date: "", notes: "", account_id: "" });
        mutate();
      } else toast.error(res.error);
    });
  }

  const startEdit = (id: string) => {
    const asset = alternativeAssets.find(a => a.id === id);
    if (!asset) return;
    setEditingId(asset.id);
    setFormData({
      name: asset.name,
      category: asset.category,
      purchase_price: asset.purchase_price.toString(),
      current_value: asset.current_value.toString(),
      purchase_date: asset.purchase_date ? new Date(asset.purchase_date).toISOString().split("T")[0] : "",
      notes: asset.notes || "", account_id: "",
    });
    setSelectedCategory(CATEGORIES.find(c => c.label === asset.category) || null);
    setShowAddModal(true);
  };

  const [deletingAsset, setDeletingAsset] = useState<{ id: string; name: string } | null>(null);

  function handleDeleteAsset(id: string, name: string) {
    setDeletingAsset({ id, name });
  }

  async function confirmDeleteAsset() {
    if (!deletingAsset) return;
    await withLock(async () => {
      const res = await deleteAlternativeAsset(deletingAsset.id);
      if (!res.error) {
        toast.success(`Asset "${deletingAsset.name}" deleted`);
        setDeletingAsset(null);
        mutate();
      } else toast.error(res.error);
    });
  }


  return (
    <div className="flex flex-col gap-8 animate-in fade-in duration-700">
      {/* Header (Only if NOT sub-component) */}
      {!isSubComponent && (
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div>
            <h1 className="text-3xl sm:text-4xl md:text-5xl font-black tracking-tight text-[--text-primary]">Alternative Assets</h1>
            <p className="text-sm md:text-sm mt-1 text-[--text-secondary]">Tangible wealth, physical assets, private equity, and holdings.</p>
          </div>
          <button 
            type="button" 
            onClick={() => {
              setEditingId(null);
              setSelectedCategory(null);
              setFormData({ name: "", category: "", purchase_price: "", current_value: "", purchase_date: new Date().toISOString().split("T")[0], notes: "", account_id: "" });
              setShowAddModal(true);
            }} 
            disabled={submitting} 
            className="btn-primary !h-11 px-6 shadow-[0_0_30px_rgba(14,165,233,0.3)] text-xs font-bold uppercase tracking-wider flex items-center gap-2 cursor-pointer"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth={2.5} viewBox="0 0 24 24"><path d="M12 4v16m8-8H4" /></svg>
            Record Asset
          </button>
        </div>
      )}

      {alternativeAssets.length === 0 ? (
        <div className="glass-card-static relative overflow-hidden p-8 md:p-16 text-center flex flex-col items-center justify-center min-h-[450px]">
          <div className="absolute -top-24 -left-24 w-96 h-96 bg-[--accent-primary]/10 rounded-full blur-[100px] pointer-events-none" />
          <div className="absolute -bottom-24 -right-24 w-96 h-96 bg-emerald-500/10 rounded-full blur-[100px] pointer-events-none" />
          <div className="relative mb-6 p-6 rounded-3xl bg-white/[0.02] border border-white/5 shadow-2xl">
            <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-[--accent-primary]/15 to-emerald-500/15 border border-[--accent-primary]/25 flex items-center justify-center shadow-[0_0_30px_-5px_rgba(14,165,233,0.3)] animate-pulse">
              <span className="text-3xl">💎</span>
            </div>
          </div>
          <h3 className="text-2xl md:text-3xl font-black text-[--text-primary] tracking-tight">Register Your First Asset</h3>
          <p className="text-sm text-[--text-muted] mt-3 max-w-lg mx-auto font-medium leading-relaxed">Track real estate, gold, collectibles, and other tangible holdings. Build a complete picture of your wealth.</p>
          <div className="mt-8 flex justify-center">
             <button onClick={() => {
               setEditingId(null);
               setSelectedCategory(null);
               setFormData({ name: "", category: "", purchase_price: "", current_value: "", purchase_date: new Date().toISOString().split("T")[0], notes: "", account_id: "" });
               setShowAddModal(true);
             }} className="btn-primary">Record New Asset</button>
          </div>
        </div>
      ) : (
      <>
        {/* Top Cards (Only if NOT sub-component) */}
        {!isSubComponent && (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
            <div className="glass-card-static p-6 border-white/5">
              <p className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted] mb-3">Asset Valuation</p>
              <p className="text-2xl md:text-3xl font-black text-white">₹{stats.totalValue.toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
              <p className="text-[0.5625rem] font-bold text-[--text-muted] mt-2 uppercase tracking-widest opacity-60">Total Market Value</p>
            </div>
            <div className="glass-card-static p-6 border-white/5">
              <p className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted] mb-3">Acquisition Cost</p>
              <p className="text-2xl md:text-3xl font-black text-[--text-secondary]">₹{stats.totalCost.toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
              <p className="text-[0.5625rem] font-bold text-[--text-muted] mt-2 uppercase tracking-widest opacity-60">Total Invested</p>
            </div>
            <div className="glass-card-static p-6 border-white/5">
              <p className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted] mb-3">Portfolio Growth</p>
              <PnLValue amount={stats.netGrowth} size="lg" showIcon currency="INR" />
              <p className="text-[0.5625rem] font-bold text-[--text-muted] mt-2 uppercase tracking-widest opacity-60">Absolute Return</p>
            </div>
            <div className="glass-card-static p-6 border-white/5">
              <p className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted] mb-3">Yield (ROI)</p>
              <p className={`text-2xl md:text-3xl font-black ${stats.netGrowth >= 0 ? "text-success" : "text-danger"}`}>
                {stats.netGrowth >= 0 ? "+" : ""}{stats.growthPercent.toFixed(2)}%
              </p>
              <p className="text-[0.5625rem] font-bold text-[--text-muted] mt-2 uppercase tracking-widest opacity-60">Relative Return</p>
            </div>
            <div className="glass-card-static p-6 border-white/5 bg-gradient-to-br from-[--accent-primary]/10 to-transparent">
              <p className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted] mb-3">Asset Count</p>
              <p className="text-xl md:text-2xl font-black text-white">{alternativeAssets.length}</p>
              <p className="text-[0.5625rem] font-bold text-[--text-muted] mt-2 uppercase tracking-widest opacity-60">Active Holdings</p>
            </div>
          </div>
        )}

        {/* Toolbar & Secondary Switcher row */}
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div className="flex flex-wrap gap-1.5 rounded-2xl bg-white/[0.02] border border-white/5 p-1.5 max-w-fit shadow-[inset_0_2px_4px_rgba(0,0,0,0.4)]">
            {[
              ...(!isSubComponent ? [{ key: "dashboard", label: "Dashboard" }] : []),
              { key: "inventory", label: "Inventory Directory", badge: alternativeAssets.length },
              { key: "history", label: "Audit History" }
            ].map((tab) => {
              const isActive = activeTab === tab.key;
              
              let activeStyles = "bg-[--accent-primary] text-white shadow-[0_0_20px_rgba(99,102,241,0.3)]";
              if (tab.key === "inventory") activeStyles = "bg-amber-500 text-white shadow-[0_0_20px_rgba(245,158,11,0.3)]";
              else if (tab.key === "history") activeStyles = "bg-slate-500 text-white shadow-[0_0_20px_rgba(100,116,139,0.3)]";

              return (
                <button
                  key={tab.key}
                  type="button"
                  onClick={() => setActiveTab(tab.key as any)}
                  className={`px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-wider transition-all duration-300 flex items-center gap-2 whitespace-nowrap active:scale-95 cursor-pointer ${
                    isActive
                      ? `${activeStyles} border border-transparent`
                      : "text-[--text-muted] hover:text-white hover:bg-white/5 border border-transparent"
                  }`}
                >
                  {tab.label}
                  {tab.badge !== undefined && (
                    <span className={`flex h-4 min-w-[1rem] items-center justify-center rounded-full px-1 text-[0.5625rem] font-black ${
                      isActive ? "bg-white/20 text-white" : "bg-white/10 text-white"
                    }`}>
                      {tab.badge}
                    </span>
                  )}
                </button>
              );
            })}
          </div>

          {isSubComponent && (
            <button 
              type="button" 
              onClick={() => {
                setEditingId(null);
                setFormData({ name: "", category: "Real Estate", purchase_price: "", current_value: "", purchase_date: new Date().toISOString().split("T")[0], notes: "", account_id: "" });
                setShowAddModal(true);
              }} 
              disabled={submitting} 
              className="btn-primary !h-10 px-5 shadow-[0_0_20px_rgba(14,165,233,0.2)] text-xs font-bold uppercase tracking-wider flex items-center gap-2 cursor-pointer"
            >
              <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" strokeWidth={2.5} viewBox="0 0 24 24"><path d="M12 4v16m8-8H4" /></svg>
              Record Asset
            </button>
          )}
        </div>

        {activeTab === "dashboard" && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <div className="glass-card-static p-6 min-h-[350px] flex flex-col">
                <div className="flex justify-between items-start mb-6">
                  <div>
                    <h3 className="text-sm font-black uppercase tracking-[0.2em] text-[--text-muted]">Top Assets</h3>
                    <p className="text-2xl font-black mt-2 text-white">Cost vs Current Value</p>
                  </div>
                </div>
                <div className="flex-1 w-full mt-4 -ml-4">
                  {mounted && barChartData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%" minWidth={1} minHeight={1}>
                      <BarChart data={barChartData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(255,255,255,0.05)" />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: "rgba(255,255,255,0.5)", fontSize: 12 }} dy={10} />
                        <YAxis axisLine={false} tickLine={false} tick={{ fill: "rgba(255,255,255,0.5)", fontSize: 12 }} tickFormatter={(val: any) => `₹${Number(val).toLocaleString()}`} />
                        <RechartsTooltip 
                          contentStyle={{ backgroundColor: "rgba(10,10,10,0.9)", border: "1px solid rgba(255,255,255,0.1)", borderRadius: "12px" }}
                          formatter={(val: any, name: any) => [`₹${Number(val).toLocaleString()}`, name]}
                        />
                        <Legend wrapperStyle={{ paddingTop: "20px" }} />
                        <Bar dataKey="Cost" fill="#64748B" radius={[4, 4, 0, 0]} />
                        <Bar dataKey="Value" fill="#14B8A6" radius={[4, 4, 0, 0]} />
                      </BarChart>
                    </ResponsiveContainer>
                  ) : (
                    <div className="flex items-center justify-center h-full text-[--text-muted] text-sm italic">No assets</div>
                  )}
                </div>
              </div>

              <div className="glass-card-static p-6 min-h-[350px] flex flex-col items-center justify-center relative">
                <h3 className="text-sm font-black uppercase tracking-[0.2em] text-[--text-muted] absolute top-6 left-6">Asset Allocation</h3>
                <div className="w-full h-[250px] mt-8">
                  {mounted && pieChartData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%" minWidth={1} minHeight={1}>
                      <PieChart>
                        <Pie data={pieChartData} cx="50%" cy="50%" innerRadius={60} outerRadius={85} paddingAngle={5} dataKey="value">
                          {pieChartData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.fill} stroke="rgba(255,255,255,0.05)" strokeWidth={2} />)}
                        </Pie>
                        <RechartsTooltip 
                          contentStyle={{ backgroundColor: "rgba(10,10,10,0.9)", border: "1px solid rgba(255,255,255,0.1)", borderRadius: "12px" }}
                          itemStyle={{ color: "#fff", fontWeight: "bold" }}
                          formatter={(value: any) => [`₹${Number(value).toLocaleString()}`, "Value"]}
                        />
                      </PieChart>
                    </ResponsiveContainer>
                  ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-[--text-muted]">
                       <span className="text-3xl mb-2">📊</span>
                       <span className="text-xs uppercase tracking-widest font-black">No Data</span>
                    </div>
                  )}
                </div>
                {pieChartData.length > 0 && (
                  <div className="flex flex-wrap justify-center gap-3 mt-4 w-full">
                    {pieChartData.map((entry, index) => (
                      <div key={index} className="flex items-center gap-1.5 text-xs">
                        <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: entry.fill }} />
                        <span className="text-[--text-secondary] font-medium">{entry.name}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {activeTab === "inventory" && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <AlternativeAssetsDataTable 
              assets={alternativeAssets}
              onEdit={startEdit}
              onDelete={handleDeleteAsset}
              onAdd={() => setShowAddModal(true)}
            />
          </div>
        )}

        {activeTab === "history" && (
          <div className="glass-card-static rounded-2xl overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="p-5 border-b border-white/5 flex items-center justify-between">
              <h3 className="text-sm font-black uppercase tracking-widest text-white">Asset Audit Trail</h3>
              <p className="text-xs font-black text-[--text-muted] uppercase tracking-widest">{assetLogs.length} Records</p>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[800px]">
                <thead>
                  <tr className="border-b border-white/5 text-[0.5625rem] text-[--text-muted] uppercase font-black tracking-widest bg-black/40">
                    <th className="py-4 px-6">Timestamp</th>
                    <th className="py-4 px-6">Action</th>
                    <th className="py-4 px-6">Details</th>
                    <th className="py-4 px-6 text-right">Amount Impact</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  {assetLogs.map((log) => {
                    const isPositive = log.action_type === "CREATE" || log.action_type === "ADJUST_UP";
                    return (
                      <tr key={log.id}>
                        <td className="py-4 px-6">
                          <p className="text-[12px] font-bold text-white/80">{log.created_at ? format(new Date(log.created_at), "MMM d, yyyy") : "N/A"}</p>
                          <p className="text-xs font-bold text-[--text-muted] mt-0.5">{log.created_at ? format(new Date(log.created_at), "HH:mm:ss") : ""}</p>
                        </td>
                        <td className="py-4 px-6">
                          <span className={`px-2 py-0.5 rounded-md text-[0.5625rem] font-black uppercase tracking-widest ${
                            log.action_type === "CREATE" ? "bg-emerald-500/10 text-emerald-400" :
                            log.action_type === "DELETE" ? "bg-rose-500/10 text-rose-400" :
                            "bg-blue-500/10 text-blue-400"
                          }`}>
                            {log.action_type}
                          </span>
                        </td>
                        <td className="py-4 px-6">
                          <p className="text-[12px] font-bold text-white">{log.details}</p>
                        </td>
                        <td className="py-4 px-6 text-right tabular-nums">
                          <p className={`text-sm font-black ${isPositive ? "text-emerald-400" : "text-rose-400"}`}>
                            {log.amount ? `${isPositive ? "+" : "-"}₹${log.amount.toLocaleString()}` : "—"}
                          </p>
                        </td>
                      </tr>
                    );
                  })}
                  {assetLogs.length === 0 && (
                    <tr>
                      <td colSpan={4} className="py-12 text-center text-xs font-bold text-[--text-muted] uppercase tracking-[0.3em]">No historical records detected</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </>
      )}

      {showAddModal && (
        <Drawer
          isOpen={showAddModal}
          onClose={() => { setShowAddModal(false); setEditingId(null); setSelectedCategory(null); setSearchQuery(""); }}
          title={editingId ? "Update Asset" : "Establish Asset"}
        >
          <div className="w-full">
            <form onSubmit={handleSubmit} className="space-y-5">
              
              {/* Search Section & Quick Category Chips - Only for new assets */}
              {!editingId && !formData.category && (
                <div className="space-y-4">
                  <div className="relative z-50">
                    <label className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted] block mb-2">Search Asset Category</label>
                    <div className="relative">
                      <input
                        type="text"
                        placeholder="Search asset category (e.g. Gold, Real Estate, Collectibles)..."
                        className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-3.5 text-sm font-bold text-white placeholder:text-white/20 focus:outline-none focus:border-[--accent-primary] transition-all shadow-inner"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        autoFocus
                      />
                    </div>
                    {searchResults.length > 0 && searchQuery.length > 0 && (
                      <div className="absolute top-full left-0 right-0 mt-2 bg-[#0A0A0A] border border-white/10 rounded-xl overflow-hidden shadow-2xl z-50 max-h-[300px] overflow-y-auto">
                        {searchResults.map((cat, idx) => (
                          <div
                            key={idx}
                            onClick={() => handleCategorySelect(cat)}
                            className="px-6 py-4 hover:bg-white/5 cursor-pointer border-b border-white/5 last:border-0 transition-colors flex justify-between items-center"
                          >
                            <div className="flex items-center gap-4">
                              <span className="text-2xl">{cat.icon}</span>
                              <div className="font-black text-white">{cat.label}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Quick Category Chips */}
                  <div className="space-y-2">
                    <label className="text-[0.65rem] font-bold text-gray-400 uppercase tracking-wider">Or Pick Category</label>
                    <div className="grid grid-cols-2 gap-2">
                      {CATEGORIES.map((cat, idx) => (
                        <button
                          key={idx}
                          type="button"
                          onClick={() => handleCategorySelect(cat)}
                          className="flex items-center gap-3 p-3 rounded-xl bg-white/[0.03] hover:bg-white/10 border border-white/5 text-left transition-all cursor-pointer"
                        >
                          <span className="text-xl">{cat.icon}</span>
                          <span className="text-xs font-bold text-white truncate">{cat.label}</span>
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              )}

              {/* Form Content - Shows if a category is selected or editing */}
              {(editingId || formData.category) && (
                <>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted]">Asset Name *</label>
                      <input 
                        required 
                        autoFocus
                        className="input-premium" 
                        placeholder="e.g. 2BHK Apartment" 
                        value={formData.name} 
                        onChange={e => setFormData({...formData, name: e.target.value})} 
                        autoComplete="off" 
                      />
                    </div>
                    <div className="space-y-2">
                      <div className="flex justify-between items-center">
                        <label className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted]">Classification</label>
                        {!editingId && (
                          <button
                            type="button"
                            onClick={() => setFormData({ ...formData, category: "" })}
                            className="text-[0.65rem] text-[--accent-primary-light] hover:underline font-bold"
                          >
                            Change
                          </button>
                        )}
                      </div>
                      <div className="input-premium flex items-center gap-3 bg-white/5 pointer-events-none">
                        <span>{selectedCategory?.icon || "💎"}</span>
                        <span className="text-white font-bold">{formData.category}</span>
                      </div>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted]">Acquisition Cost (₹) *</label>
                      <input 
                        required 
                        type="number" 
                        className="input-premium tabular-nums" 
                        placeholder="0"
                        value={formData.purchase_price} 
                        onChange={e => setFormData({...formData, purchase_price: e.target.value})} 
                        autoComplete="off" 
                        inputMode="decimal" 
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted]">Current Valuation (₹) *</label>
                      <input 
                        required 
                        type="number" 
                        className="input-premium tabular-nums" 
                        placeholder="0"
                        value={formData.current_value} 
                        onChange={e => setFormData({...formData, current_value: e.target.value})} 
                        autoComplete="off" 
                        inputMode="decimal" 
                      />
                    </div>
                  </div>

                  <details className="group glass-card-static border border-white/5 rounded-xl overflow-hidden mt-4">
                    <summary className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted] p-3.5 cursor-pointer outline-none hover:text-white transition-colors bg-white/[0.01] flex items-center justify-between">
                      <span>Additional Details (Date, Account, Notes)</span>
                      <span className="text-xs text-white/40 group-open:rotate-180 transition-transform">▼</span>
                    </summary>
                    <div className="p-4 pt-2 space-y-4">
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="space-y-2">
                          <label className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted]">Acquisition Date</label>
                          <input 
                            type="date" 
                            className="input-premium" 
                            value={formData.purchase_date} 
                            onChange={e => setFormData({...formData, purchase_date: e.target.value})} 
                          />
                        </div>
                        <div className="space-y-2">
                          <label className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted]">Source Account (Optional)</label>
                          <select 
                            aria-label="Select account" 
                            className="input-premium" 
                            value={formData.account_id} 
                            onChange={e => setFormData({...formData, account_id: e.target.value})}
                          >
                            <option value="" className="bg-[#181A20] text-white font-medium">No Transaction</option>
                            {accounts.map(acc => {
                              const symbol = acc.currency === "USD" ? "$" : "₹";
                              const nameLabel = acc.bank_name && acc.bank_name.trim().toLowerCase() !== acc.name.trim().toLowerCase()
                                ? `${acc.bank_name} (${acc.name})`
                                : acc.name;
                              return (
                                <option key={acc.id} value={acc.id} className="bg-[#181A20] text-white font-medium">
                                  {nameLabel} — {symbol}{acc.balance.toLocaleString()}
                                </option>
                              );
                            })}
                          </select>
                        </div>
                      </div>

                      <div className="space-y-2">
                        <label className="text-xs font-black uppercase tracking-[0.2em] text-[--text-muted]">Notes / Location</label>
                        <input 
                          type="text" 
                          className="input-premium" 
                          placeholder="Optional notes..." 
                          value={formData.notes} 
                          onChange={e => setFormData({...formData, notes: e.target.value})} 
                          autoComplete="off" 
                        />
                      </div>
                    </div>
                  </details>

                  <div className="pt-2 mt-6">
                    <button type="submit" disabled={submitting} className="btn-primary w-full h-12 shadow-xl shadow-[--accent-primary]/20 text-xs font-black uppercase tracking-widest cursor-pointer">
                      {submitting ? "Processing..." : editingId ? "Update Asset" : "Establish Asset"}
                    </button>
                  </div>
                </>
              )}
              
              {/* If no category selected, show fallback for manual entry */}
              {!editingId && !formData.category && (
                <div className="text-center p-8 bg-white/5 border border-white/10 rounded-2xl">
                  <p className="text-[--text-muted] mb-4">Or create a custom asset directly.</p>
                  <button type="button" onClick={() => setFormData({ ...formData, category: "Others" })} className="btn-secondary px-6 py-3 text-xs font-black uppercase tracking-widest">
                    Manual Entry
                  </button>
                </div>
              )}
            </form>
          </div>
        </Drawer>
      )}

      {/* Delete Asset Custom Modal */}
      {deletingAsset && (
        <Drawer isOpen={!!deletingAsset} onClose={() => setDeletingAsset(null)} title="Delete Asset?" variant="center">
          <div className="p-4 space-y-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-2xl bg-rose-500/10 border border-rose-500/20 flex items-center justify-center text-rose-400">
                <Trash2 className="w-5 h-5" />
              </div>
              <div>
                <h3 className="text-base font-bold text-white">Delete Asset Record</h3>
                <p className="text-xs text-[--text-muted]">Are you sure you want to delete &quot;{deletingAsset.name}&quot;?</p>
              </div>
            </div>
            <div className="flex gap-3 pt-2">
              <button type="button" onClick={() => setDeletingAsset(null)} className="btn-secondary flex-1">Cancel</button>
              <button type="button" onClick={confirmDeleteAsset} className="btn-danger flex-1" disabled={submitting}>
                {submitting ? "Deleting..." : "Delete Asset"}
              </button>
            </div>
          </div>
        </Drawer>
      )}
    </div>
  );
}
